DEFAULT_SETTINGS = {
    "timeout": 30,
    "retry_count": 3,
    "log_level": "INFO",
}


def load_settings_with_defaults(user_settings):
    """Merge user-provided settings over the module-level DEFAULT_SETTINGS.

    Any key present in user_settings overrides the corresponding default;
    keys not mentioned by the caller fall back to DEFAULT_SETTINGS.
    """
    merged_settings = dict(DEFAULT_SETTINGS)
    merged_settings.update(user_settings)
    return merged_settings
